public class CinemaShow{private String title;private int seatsAvailable;private final int capacity;private static int totalBooked=0;CinemaShow(String t,int c){title=t;capacity=c;seatsAvailable=c;}CinemaShow(String t){this(t,100);}boolean book(int n){if(n<=0||n>seatsAvailable)return false;seatsAvailable-=n;totalBooked+=n;return true;}void cancel(int n){if(n>0)seatsAvailable=Math.min(capacity,seatsAvailable+n);}int getSeatsAvailable(){return seatsAvailable;}static int getTotalBooked(){return totalBooked;}public static void main(String[]x){CinemaShow s=new CinemaShow("Java",5);System.out.println(s.book(3)+" seats="+s.seatsAvailable);System.out.println(s.book(4)+" seats="+s.seatsAvailable);s.cancel(1);System.out.println("Available="+s.getSeatsAvailable()+", booked="+getTotalBooked());}}
